&lt;div class=&quot;presentation navmenudroite&quot;&gt;
&lt;h2 class=&quot;separator&quot;&gt;Les arch&#233;types de sorci&#232;re&lt;a class=&quot;headeranchor&quot; id=&quot;Les_arch&#233;types_de_sorci&#232;re_0&quot; href=&quot;#Les_arch&#233;types_de_sorci&#232;re_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&amp;nbsp;Retour &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Sorci&#232;re.html&quot; title=&quot;La sorci&#232;re&quot;&gt;classe&lt;/a&gt;.
&lt;ul style=&quot;margin-top:2px&quot;&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Amie-Des-Animaux-(Sorci&#232;re).html&quot; title=&quot;Amie des animaux&quot;&gt;Amie des animaux&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Buda-(Sorci&#232;re).html&quot; title=&quot;Buda&quot;&gt;Buda&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Gnoll.html&quot; title=&quot;Gnoll&quot;&gt;Gnoll&lt;/a&gt;) (CM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Canalisatrice-De-Mal&#233;fices-(Sorci&#232;re).html&quot; title=&quot;Canalisatrice de mal&#233;fices&quot;&gt;Canalisatrice de mal&#233;fices&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gu&#233;risseuse-Balafr&#233;e-(Sorci&#232;re).html&quot; title=&quot;Gu&#233;risseuse balafr&#233;e&quot;&gt;Gu&#233;risseuse balafr&#233;e&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Orque-(Race).html&quot; title=&quot;Les orques&quot;&gt;Orque&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Marchetombe-(Sorci&#232;re).html&quot; title=&quot;Marchetombe&quot;&gt;Marchetombe&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Occultiste-Des-Dimensions-(Sorci&#232;re).html&quot; title=&quot;Occultiste des dimensions&quot;&gt;Occultiste des dimensions&lt;/a&gt; (RSE)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Protectrice-Des-Lignes-Telluriques-(Sorci&#232;re).html&quot; title=&quot;Protectrice des lignes telluriques&quot;&gt;Protectrice des lignes telluriques&lt;/a&gt; (AO)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sorci&#232;re-Aux-Toxines-(Sorci&#232;re).html&quot; title=&quot;Sorci&#232;re aux toxines&quot;&gt;Sorci&#232;re aux toxines&lt;/a&gt;&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sorci&#232;re-De-Lhiver-(Sorci&#232;re).html&quot; title=&quot;Sorci&#232;re de l&amp;#39;hiver&quot;&gt;Sorci&#232;re de l&#39;hiver&lt;/a&gt; (MMI)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sorci&#232;re-Des-Mers-(Sorci&#232;re).html&quot; title=&quot;Sorci&#232;re des mers&quot;&gt;Sorci&#232;re des mers&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sorci&#232;re-De-Village-(Sorci&#232;re).html&quot; title=&quot;Sorci&#232;re de village&quot;&gt;Sorci&#232;re de village&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sorci&#232;re-Des-Montagnes-(Sorci&#232;re).html&quot; title=&quot;Sorci&#232;re des montagnes&quot;&gt;Sorci&#232;re des montagnes&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sorci&#232;re-Li&#233;e-(Sorci&#232;re).html&quot; title=&quot;Sorci&#232;re li&#233;e&quot;&gt;Sorci&#232;re li&#233;e&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Demi-Elfe.html&quot; title=&quot;Les demi-elfes&quot;&gt;Demi-elfe&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Synergiste-(Sorci&#232;re).html&quot; title=&quot;Synergiste&quot;&gt;Synergiste&lt;/a&gt; (&lt;i&gt;FF&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Tisseuse-De-R&#234;ves-(Sorci&#232;re).html&quot; title=&quot;Tisseuse de r&#234;ves&quot;&gt;Tisseuse de r&#234;ves&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Changelin-(Race).html&quot; title=&quot;Les changelins&quot;&gt;Changelin&lt;/a&gt;) (MR)&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;&lt;script&gt;
$(function () {
  let image = &quot;Illustrations/PNJ/Changelin.jpg&quot;;
  if(image == &quot;&quot; || image == &quot; &quot;) { $(&#39;.symbole2&#39;).html(&quot;&quot;); }
});
&lt;/script&gt;
&lt;div class=&quot;presentation navmenudroite&quot; style=&quot;margin-bottom:5px&quot;&gt;
&lt;table width=&quot;80px&quot;&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;
&lt;td class=&quot;symbole2&quot;&gt;&lt;abbr title=&quot;Cette option est plus sp&#233;cifique, voire r&#233;serv&#233;e, aux membres de la race indiqu&#233;e. Discutez avec votre MJ de sa disponibilit&#233; pour votre personnage.&quot;&gt;&lt;a href=&quot;./Pathfinder-RPG.Changelin (race).ashx&quot;&gt;&lt;img src=&quot;/wiki/public/upload/Illustrations/PNJ/Changelin.jpg&quot; width=&quot;80%&quot; style=&quot;float:center; margin: 0px -50px 0px 7px; border: 1px solid #4b3124&quot;&gt;&lt;/a&gt;&lt;/abbr&gt;&lt;/td&gt;
&lt;/tr&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;
&lt;td&gt;&lt;div style=&quot;text-align:center; font-size: 81%; font-weight: bold;&quot;&gt;Option plus&lt;br /&gt;commune chez&lt;br /&gt;les &lt;a class=&quot;pagelink&quot; href=&quot;Changelin-(Race).html&quot; title=&quot;Les changelins&quot;&gt;changelins&lt;/a&gt;.&lt;/div&gt;&lt;/td&gt;
&lt;/tr&gt;&lt;/table&gt;
&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Manuel des races (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Advanced Race Guide, Elves of Golarion, Gnomes of Golarion, Goblins of Golarion, Halflings of Golarion, Humans of Golarion, Dwarves of Golarion, Orcs of Golarion/Manuel des races&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoMR.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;
&lt;i&gt;La changelin tisseuse de r&#234;ves se sert de son h&#233;ritage de guenaude pour manipuler les royaumes du r&#234;ve et toucher l’esprit et l’&#226;me des mortels, que ce soit pour faire le Bien ou le Mal.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Comp&#233;tences de classe&lt;a class=&quot;headeranchor&quot; id=&quot;Comp&#233;tences_de_classe_0&quot; href=&quot;#Comp&#233;tences_de_classe_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;La tisseuse de r&#234;ves ajoute &lt;a class=&quot;pagelink&quot; href=&quot;Psychologie.html&quot; title=&quot;Psychologie&quot;&gt;Psychologie&lt;/a&gt; &#224; sa liste de comp&#233;tences de classe, mais en retire &lt;a class=&quot;pagelink&quot; href=&quot;Premiers-Secours.html&quot; title=&quot;Premiers secours&quot;&gt;Premiers secours&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Protecteur&lt;a class=&quot;headeranchor&quot; id=&quot;Protecteur_1&quot; href=&quot;#Protecteur_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Ce sont en principe les &lt;a class=&quot;pagelink&quot; href=&quot;Protecteurs.html#PRESAGES&quot; title=&quot;Les protecteurs de la sorci&#232;re&quot;&gt;pr&#233;sages&lt;/a&gt; ou les &lt;a class=&quot;pagelink&quot; href=&quot;Protecteurs.html#ETOILES&quot; title=&quot;Les protecteurs de la sorci&#232;re&quot;&gt;&#233;toiles&lt;/a&gt; qui prot&#232;gent la tisseuse de r&#234;ves.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Sorts de la Tisseuse de r&#234;ves&lt;a class=&quot;headeranchor&quot; id=&quot;Sorts_de_la_Tisseuse_de_r&#234;ves_2&quot; href=&quot;#Sorts_de_la_Tisseuse_de_r&#234;ves_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;La tisseuse de r&#234;ves remplace certains des sorts de son protecteur par les suivants : 2– &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Implantation-De-Pens&#233;es.html&quot; title=&quot;Implantation de pens&#233;es&quot;&gt;implantation de pens&#233;es&lt;/a&gt;&lt;/i&gt;, 4– &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Poussi&#232;re-Du-Cr&#233;puscule.html&quot; title=&quot;Poussi&#232;re du cr&#233;puscule&quot;&gt;poussi&#232;re du cr&#233;puscule&lt;/a&gt;&lt;/i&gt;, 6– &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sommeil-Profond.html&quot; title=&quot;Sommeil profond&quot;&gt;sommeil profond&lt;/a&gt;&lt;/i&gt;, 8– &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Modification-De-M&#233;moire.html&quot; title=&quot;Modification de m&#233;moire&quot;&gt;modification de m&#233;moire&lt;/a&gt;&lt;/i&gt;, 10– &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Songe.html&quot; title=&quot;Songe&quot;&gt;songe&lt;/a&gt;&lt;/i&gt;, 12– &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Manteau-De-R&#234;ves.html&quot; title=&quot;Manteau de r&#234;ves&quot;&gt;manteau de r&#234;ves&lt;/a&gt;&lt;/i&gt;, 14– &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Forme-&#201;th&#233;r&#233;e.html&quot; title=&quot;Forme &#233;th&#233;r&#233;e&quot;&gt;forme &#233;th&#233;r&#233;e&lt;/a&gt;&lt;/i&gt;, 16– &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Moment-De-Prescience.html&quot; title=&quot;Moment de prescience&quot;&gt;moment de prescience&lt;/a&gt;&lt;/i&gt;, 18– &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Projection-Astrale.html&quot; title=&quot;Projection astrale&quot;&gt;projection astrale&lt;/a&gt;&lt;/i&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Fileuse de r&#234;ves (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Fileuse_de_r&#234;ves_Sur_3&quot; href=&quot;#Fileuse_de_r&#234;ves_Sur_3&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 2, lorsque la tisseuse de r&#234;ves lance un sort &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;er-Un-Sort#Registre.html&quot; title=&quot;Registre&quot;&gt;mental&lt;/a&gt; sur une cible qu’elle a endormie au moyen de son mal&#233;fice de &lt;a class=&quot;pagelink&quot; href=&quot;Mal&#233;fices.html#SOMMEIL&quot; title=&quot;Les mal&#233;fices de la sorci&#232;re&quot;&gt;sommeil&lt;/a&gt; ou d’un sort qu’elle a lanc&#233;, elle ajoute +1 au &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; du sort mental. Si la cible r&#233;ussit son &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jet de sauvegarde&lt;/a&gt; contre le sort, elle ne se r&#233;veille pas et n’aura aucun souvenir d’avoir r&#233;sist&#233; au sort. Si c’est appropri&#233;, la tisseuse de r&#234;ves peut int&#233;grer des &#233;l&#233;ments d’un sort mental (comme, par exemple, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Implantation-De-Pens&#233;es.html&quot; title=&quot;Implantation de pens&#233;es&quot;&gt;implantation de pens&#233;es&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Suggestion.html&quot; title=&quot;Suggestion&quot;&gt;suggestion&lt;/a&gt;&lt;/i&gt;, etc.) au subconscient de la cible afin de lui faire croire que les effets du sort trouvent leur origine dans le r&#234;ve (les d&#233;tails concernant la mani&#232;re dont ces &#233;l&#233;ments s’int&#232;grent au r&#234;ve d&#233;pendent du MJ). Cette capacit&#233; remplace le &lt;a class=&quot;pagelink&quot; href=&quot;Sorci&#232;re.html#MALEFICE&quot; title=&quot;La sorci&#232;re&quot;&gt;mal&#233;fice&lt;/a&gt; que gagne la sorci&#232;re au niveau 2.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Voleuse de r&#234;ves (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Voleuse_de_r&#234;ves_Sur_4&quot; href=&quot;#Voleuse_de_r&#234;ves_Sur_4&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 6, la tisseuse de r&#234;ves peut alt&#233;rer l’esprit en sommeil de toute cr&#233;ature qu’elle a endormie au moyen de son mal&#233;fice de &lt;a class=&quot;pagelink&quot; href=&quot;Mal&#233;fices.html#SOMMEIL&quot; title=&quot;Les mal&#233;fices de la sorci&#232;re&quot;&gt;sommeil&lt;/a&gt; ou d’un sort qu’elle a lanc&#233;. Elle peut refa&#231;onner l’un des souvenirs de la cible comme si elle utilisait &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Modification-De-M&#233;moire.html&quot; title=&quot;Modification de m&#233;moire&quot;&gt;modification de m&#233;moire&lt;/a&gt;&lt;/i&gt;. Sinon, elle peut se faufiler dans ses souvenirs oniriques, incitant l’esprit de cette derni&#232;re &#224; lui r&#233;v&#233;ler certaines informations sp&#233;cifiques ; le subconscient du r&#234;veur peut r&#233;sister ou essayer de tromper la sorci&#232;re avec des souvenirs hors contexte, un peu comme un corps peut r&#233;sister lorsqu’on l’interroge au moyen de &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Communication-Avec-Les-Morts.html&quot; title=&quot;Communication avec les morts&quot;&gt;communication avec les morts&lt;/a&gt;&lt;/i&gt;. Un jet de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Volont&#233;&quot;&gt;Volont&#233;&lt;/a&gt; permet d’annuler cet effet (&lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; &#233;gal &#224; celui du &lt;a class=&quot;pagelink&quot; href=&quot;Sorci&#232;re.html#MALEFICE&quot; title=&quot;La sorci&#232;re&quot;&gt;mal&#233;fice&lt;/a&gt; de la sorci&#232;re). Que le jet soit r&#233;ussi ou non, la cr&#233;ature ne peut plus &#234;tre prise pour cible de ce mal&#233;fice pendant une journ&#233;e. Cette capacit&#233; remplace le &lt;a class=&quot;pagelink&quot; href=&quot;Sorci&#232;re.html#MALEFICE&quot; title=&quot;La sorci&#232;re&quot;&gt;mal&#233;fice&lt;/a&gt; que la sorci&#232;re gagne au niveau 6.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Possession onirique&lt;a class=&quot;headeranchor&quot; id=&quot;Possession_onirique_5&quot; href=&quot;#Possession_onirique_5&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 10, la tisseuse de r&#234;ves peut prendre le contr&#244;le de toute cr&#233;ature qu’elle a endormie au moyen de son mal&#233;fice de &lt;a class=&quot;pagelink&quot; href=&quot;Mal&#233;fices.html#SOMMEIL&quot; title=&quot;Les mal&#233;fices de la sorci&#232;re&quot;&gt;sommeil&lt;/a&gt; ou d’un sort qu’elle a lanc&#233;. Cet effet fonctionne comme &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Possession.html&quot; title=&quot;Possession&quot;&gt;possession&lt;/a&gt;&lt;/i&gt;, le &lt;a class=&quot;pagelink&quot; href=&quot;Sorci&#232;re.html#FAMILIER&quot; title=&quot;La sorci&#232;re&quot;&gt;familier&lt;/a&gt; de la sorci&#232;re faisant office d’&#226;me-r&#233;ceptacle. Un jet de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Volont&#233;&quot;&gt;Volont&#233;&lt;/a&gt; permet d’annuler cet effet (&lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; &#233;gal &#224; celui du &lt;a class=&quot;pagelink&quot; href=&quot;Sorci&#232;re.html#MALEFICE&quot; title=&quot;La sorci&#232;re&quot;&gt;mal&#233;fice&lt;/a&gt; de la sorci&#232;re). Que le jet soit r&#233;ussi ou non, la cr&#233;ature ne peut plus &#234;tre prise pour cible de ce mal&#233;fice pendant une journ&#233;e. Cette capacit&#233; remplace le &lt;a class=&quot;pagelink&quot; href=&quot;Sorci&#232;re.html#MALEFICE&quot; title=&quot;La sorci&#232;re&quot;&gt;mal&#233;fice&lt;/a&gt; que la sorci&#232;re gagne au niveau 10.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Mal&#233;fices conseill&#233;s&lt;a class=&quot;headeranchor&quot; id=&quot;Mal&#233;fices_conseill&#233;s_6&quot; href=&quot;#Mal&#233;fices_conseill&#233;s_6&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Les mal&#233;fices suivants compl&#232;tent l’arch&#233;type de la tisseuse de r&#234;ves :
&lt;ul&gt;&lt;li&gt;&lt;b&gt;Mal&#233;fices.&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Mal&#233;fices.html#Charme&quot; title=&quot;Les mal&#233;fices de la sorci&#232;re&quot;&gt;charme&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Mal&#233;fices.html#Sommeil&quot; title=&quot;Les mal&#233;fices de la sorci&#232;re&quot;&gt;sommeil&lt;/a&gt; ; &lt;a class=&quot;pagelink&quot; href=&quot;Mal&#233;fices.html#Oiseaudemauvaisaugure&quot; title=&quot;Les mal&#233;fices de la sorci&#232;re&quot;&gt;oiseau de mauvais augure&lt;/a&gt;.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Mal&#233;fices majeurs.&lt;/b&gt;  &lt;a class=&quot;pagelink&quot; href=&quot;Mal&#233;fices.html#Cauchemars&quot; title=&quot;Les mal&#233;fices de la sorci&#232;re&quot;&gt;cauchemars&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Mal&#233;fices.html#Vision&quot; title=&quot;Les mal&#233;fices de la sorci&#232;re&quot;&gt;vision&lt;/a&gt;.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Grands Mal&#233;fices.&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Mal&#233;fices.html#Sommeil&#233;ternel&quot; title=&quot;Les mal&#233;fices de la sorci&#232;re&quot;&gt;sommeil &#233;ternel&lt;/a&gt; ; &lt;a class=&quot;pagelink&quot; href=&quot;Mal&#233;fices.html#Sinistreproph&#233;tie&quot; title=&quot;Les mal&#233;fices de la sorci&#232;re&quot;&gt;sinistre proph&#233;tie&lt;/a&gt;.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;
